const data = $input.item.json.callback_query.data;
const parts = data.split('|');

return {
  theme: parts[0],
  nombre: parts[1],
  chatId: $input.item.json.callback_query.message.chat.id
};

// 1. Theme viene limpio de Telegram (fix aplicado en el callback_data de "Botones Claro/Oscuro")
const rawTheme = $input.item.json.theme || 'claro';
const theme = rawTheme.trim().toLowerCase();

// 2. Obtenemos el nombre
const nombre = $input.item.json.nombre || 'Participante';

// 3. Generamos la fecha exacta de Perú directamente aquí (evitamos errores de nodos anteriores)
const opcionesFecha = { timeZone: 'America/Lima', day: '2-digit', month: '2-digit', year: 'numeric' };
const fecha = new Intl.DateTimeFormat('es-PE', opcionesFecha).format(new Date());

// 4. Logos: fuente unica en static data (ver nodo "Cargar Logos")
const staticData = $getWorkflowStaticData('global');
const base64Logo = theme === 'claro' ? staticData.base64LogoClaro : staticData.base64LogoOscuro;

// 5. Generamos el HTML (con fix para forzar impresión de colores de fondo)
let html = `<!DOCTYPE html>
<html lang="es">
<head>
    <meta charset="UTF-8">
    <title>Certificado DSC UTP</title>
    <style>
        @page { size: A4 landscape; margin: 0; }
        * { -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; }
        body { 
            font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; 
            margin: 0; padding: 0; 
            display: flex; justify-content: center; align-items: center; height: 100vh;
            ${theme === 'claro' ? 'background-color: #ffffff; color: #202124;' : 'background-color: #0f0f11; color: #e8eaed;'}
        }
        .certificado-container {
            width: 90vw; height: 85vh;
            border-radius: 15px;
            padding: 40px; text-align: center; position: relative;
            box-sizing: border-box;
            ${theme === 'claro' ? 'border: 8px solid #f8f9fa; box-shadow: 0 0 20px rgba(0,0,0,0.05); background: radial-gradient(circle, rgba(26,115,232,0.02) 0%, rgba(255,255,255,0) 70%);' : 'background-color: #16161a; border: 2px solid #24242b; box-shadow: 0 10px 40px rgba(0,0,0,0.6); background: radial-gradient(circle, rgba(66,133,244,0.04) 0%, rgba(22,22,26,0) 80%);'}
        }
        .header { margin-bottom: 20px; }
        .logo { width: 140px; margin-bottom: 15px; ${theme === 'oscuro' ? 'filter: drop-shadow(0 4px 8px rgba(0,0,0,0.3));' : ''} }
        .title { font-size: 38pt; font-weight: 700; color: ${theme === 'claro' ? '#1a73e8' : '#8ab4f8'}; margin: 0; letter-spacing: 2px; }
        .subtitle { font-size: 16pt; color: ${theme === 'claro' ? '#5f6368' : '#9aa0a6'}; margin-top: 10px; font-weight: 500; }
        .content { margin-top: 40px; }
        .presented-to { font-size: 18pt; color: ${theme === 'claro' ? '#3c4043' : '#bdc1c6'}; margin-bottom: 15px; }
        .name { font-size: 42pt; font-weight: bold; border-bottom: 3px solid ${theme === 'claro' ? '#1a73e8' : '#8ab4f8'}; display: inline-block; padding-bottom: 5px; margin-bottom: 25px; min-width: 400px; color: ${theme === 'claro' ? '#202124' : '#ffffff'}; }
        .reason { font-size: 14pt; line-height: 1.6; max-width: 850px; margin: 0 auto; color: ${theme === 'claro' ? '#3c4043' : '#9aa0a6'}; }
        .footer { 
            position: absolute; bottom: 50px; left: 0; width: 100%; 
            display: flex; justify-content: space-around; align-items: flex-end; 
        }
        .signature-box { text-align: center; width: 250px; }
        .signature-line { border-top: 2px solid ${theme === 'claro' ? '#dadce0' : '#3c4043'}; padding-top: 10px; font-weight: 600; font-size: 12pt; color: ${theme === 'claro' ? '#3c4043' : '#bdc1c6'}; }
        .decorations { position: absolute; top: 0; left: 0; width: 100%; height: 12px; display: flex; border-top-left-radius: 7px; border-top-right-radius: 7px; overflow: hidden; }
        .color-bar { height: 100%; flex: 1; }
        .blue { background-color: #4285F4; } .light-blue { background-color: #25A4D6; }
        .yellow { background-color: #FABB05; } .orange { background-color: #F67C00; }
    </style>
</head>
<body>
    <div class="certificado-container">
        <div class="decorations">
            <div class="color-bar blue"></div><div class="color-bar light-blue"></div>
            <div class="color-bar yellow"></div><div class="color-bar orange"></div>
        </div>
        <div class="header">
            <img src="data:image/png;base64,${base64Logo}" alt="DSC UTP Logo" class="logo">
            <h1 class="title">CERTIFICADO DE CULMINACIÓN</h1>
            <p class="subtitle">Developer Student Club - Universidad Tecnológica del Perú</p>
        </div>
        <div class="content">
            <p class="presented-to">Se otorga el presente certificado a:</p>
            <div class="name">${nombre}</div>
            <p class="reason">Por su destacada participación y culminación exitosa en el programa de desarrollo y tecnología, demostrando compromiso con el aprendizaje y la comunidad del DSC UTP.</p>
        </div>
        <div class="footer">
            <div class="signature-box">
                <div class="signature-line">DSC Lead</div>
            </div>
            <div class="signature-box">
                <div class="signature-line">${fecha}</div>
            </div>
        </div>
    </div>
</body>
</html>`;

// 6. Convertir el texto HTML a un buffer (archivo binario) real
const htmlBuffer = Buffer.from(html, 'utf8');

return {
  json: {
    chatId: $input.item.json.chatId
  },
  binary: {
    mi_archivo_html: {
      data: htmlBuffer.toString('base64'),
      mimeType: 'text/html',
      fileName: 'index.html'
    }
  }
};

const nombre = `${$json['Nombres'] || ''} ${$json['Apellidos'] || ''}`.trim();
const temaRaw = ($json['Tema'] || 'claro').toString().trim().toLowerCase();
const theme = temaRaw.includes('oscuro') ? 'oscuro' : 'claro';

return {
  theme,
  nombre,
  chatId: $('Comando o Botón').item.json.message.chat.id
};

const items = $input.all();

// Logos: misma fuente unica que usa "Generate HTML" (nodo "Cargar Logos")
const staticData = $getWorkflowStaticData('global');
const base64LogoClaro = staticData.base64LogoClaro;
const base64LogoOscuro = staticData.base64LogoOscuro;

const opcionesFecha = { timeZone: 'America/Lima', day: '2-digit', month: '2-digit', year: 'numeric' };
const fecha = new Intl.DateTimeFormat('es-PE', opcionesFecha).format(new Date());

function certificadoHTML(nombre, theme) {
  const base64Logo = theme === 'claro' ? base64LogoClaro : base64LogoOscuro;
  const bg = theme === 'claro' ? '#ffffff' : '#0f0f11';
  const txt = theme === 'claro' ? '#202124' : '#e8eaed';
  const accent = theme === 'claro' ? '#1a73e8' : '#8ab4f8';
  const sub = theme === 'claro' ? '#5f6368' : '#9aa0a6';
  const reason = theme === 'claro' ? '#3c4043' : '#9aa0a6';
  const line = theme === 'claro' ? '#dadce0' : '#3c4043';

  return `
  <div class="page" style="background-color:${bg}; color:${txt};">
    <div class="certificado-container">
      <div class="decorations">
        <div class="color-bar blue"></div><div class="color-bar light-blue"></div>
        <div class="color-bar yellow"></div><div class="color-bar orange"></div>
      </div>
      <div class="header">
        <img src="data:image/png;base64,${base64Logo}" alt="DSC UTP Logo" class="logo">
        <h1 class="title" style="color:${accent};">CERTIFICADO DE CULMINACIÓN</h1>
        <p class="subtitle" style="color:${sub};">Developer Student Club - Universidad Tecnológica del Perú</p>
      </div>
      <div class="content">
        <p class="presented-to" style="color:${reason};">Se otorga el presente certificado a:</p>
        <div class="name" style="border-bottom-color:${accent}; color:${txt};">${nombre}</div>
        <p class="reason" style="color:${reason};">Por su destacada participación y culminación exitosa en el programa de desarrollo y tecnología, demostrando compromiso con el aprendizaje y la comunidad del DSC UTP.</p>
      </div>
      <div class="footer">
        <div class="signature-box"><div class="signature-line" style="border-top-color:${line}; color:${reason};">DSC Lead</div></div>
        <div class="signature-box"><div class="signature-line" style="border-top-color:${line}; color:${reason};">${fecha}</div></div>
      </div>
    </div>
  </div>`;
}

const paginas = items.map(item => {
  const theme = (item.json.theme || 'claro').toString().trim().toLowerCase();
  const nombre = item.json.nombre || 'Participante';
  return certificadoHTML(nombre, theme);
}).join('\n');

const html = `<!DOCTYPE html>
<html lang="es">
<head>
<meta charset="UTF-8">
<style>
  @page { size: A4 landscape; margin: 0; }
  * { -webkit-print-color-adjust: exact !important; print-color-adjust: exact !important; }
  body { margin: 0; padding: 0; font-family: 'Segoe UI', Roboto, Helvetica, Arial, sans-serif; }
  .page { width: 100vw; height: 100vh; display: flex; justify-content: center; align-items: center; page-break-after: always; box-sizing: border-box; }
  .page:last-child { page-break-after: auto; }
  .certificado-container { width: 90vw; height: 85vh; border-radius: 15px; padding: 40px; text-align: center; position: relative; box-sizing: border-box; box-shadow: 0 10px 40px rgba(0,0,0,0.15); }
  .header { margin-bottom: 20px; }
  .logo { width: 140px; margin-bottom: 15px; }
  .title { font-size: 38pt; font-weight: 700; margin: 0; letter-spacing: 2px; }
  .subtitle { font-size: 16pt; margin-top: 10px; font-weight: 500; }
  .content { margin-top: 40px; }
  .presented-to { font-size: 18pt; margin-bottom: 15px; }
  .name { font-size: 42pt; font-weight: bold; border-bottom: 3px solid; display: inline-block; padding-bottom: 5px; margin-bottom: 25px; min-width: 400px; }
  .reason { font-size: 14pt; line-height: 1.6; max-width: 850px; margin: 0 auto; }
  .footer { position: absolute; bottom: 50px; left: 0; width: 100%; display: flex; justify-content: space-around; align-items: flex-end; }
  .signature-box { text-align: center; width: 250px; }
  .signature-line { border-top: 2px solid; padding-top: 10px; font-weight: 600; font-size: 12pt; }
  .decorations { position: absolute; top: 0; left: 0; width: 100%; height: 12px; display: flex; overflow: hidden; }
  .color-bar { height: 100%; flex: 1; }
  .blue { background-color: #4285F4; } .light-blue { background-color: #25A4D6; }
  .yellow { background-color: #FABB05; } .orange { background-color: #F67C00; }
</style>
</head>
<body>
${paginas}
</body>
</html>`;

const htmlBuffer = Buffer.from(html, 'utf8');

return {
  json: {
    chatId: $('Comando o Botón').first().json.message.chat.id
  },
  binary: {
    mi_archivo_html: {
      data: htmlBuffer.toString('base64'),
      mimeType: 'text/html',
      fileName: 'index.html'
    }
  }
};

// Fuente unica de los logos: se guardan en static data del workflow
// para no duplicar este blob base64 en cada nodo que genera HTML.
const staticData = $getWorkflowStaticData('global');
staticData.base64LogoClaro = "";
staticData.base64LogoOscuro = "";

return $input.all();
